head.script:
scwin.onpageload = function() {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
};
scwin.onpageunload = function() {};
scwin.trigger2_onclick = function(e) {
    var options = {
        id: "popPsnlCertiInq",
        type: "wframePopup",
        width: "700px",
        height: "400px",
        top: "130px",
        left: "200px",
        popupName: "교직원검색",
        modal: true,
        resizable: true
    };
    // 팝업 생성.
    $p.openPopup("popup_closePopup_WPFF-408_(WSQ-4076)_sub.xml", options);
};
scwin.trigger3_onclick = function(e) {
    var options = {
        id: "popPsnlCertiInq",
        type: "iframePopup",
        width: "700px",
        height: "400px",
        top: "130px",
        left: "200px",
        popupName: "교직원검색",
        modal: true,
        resizable: true
    };
    // 팝업 생성.
    $p.openPopup("popup_closePopup_WPFF-408_(WSQ-4076)_sub.xml", options);
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById('popPsnlCertiInq') == null
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger2').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('popPsnlCertiInq_wframe_trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
